CREATE TABLE eco_collect.accounts (user_id text PRIMARY KEY, email text NOT NULL, name text NOT NULL, phone text NOT NULL DEFAULT '', company text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE eco_collect.requests (id uuid PRIMARY KEY, user_id text NOT NULL REFERENCES eco_collect.accounts(user_id), location text NOT NULL, kind text NOT NULL, quantity text NOT NULL, pickup_date date NOT NULL, notes text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','reviewing','quoted','accepted','scheduled','completed','cancelled')), quote_fils integer CHECK(quote_fils > 0), quote_notes text NOT NULL DEFAULT '', scheduled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX requests_user_created ON eco_collect.requests(user_id,created_at DESC);
CREATE TABLE eco_collect.events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, request_id uuid NOT NULL REFERENCES eco_collect.requests(id), actor_id text NOT NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE eco_collect.rate_limits (user_id text NOT NULL, bucket bigint NOT NULL, count integer NOT NULL DEFAULT 1, PRIMARY KEY(user_id,bucket));
